def update_exam45():
    with open('data/exams.json', 'r', encoding='utf-8') as f:
        exams = json.load(f)

    updated = False
    for i, ex in enumerate(exams):
        if ex['id'] == 'exam-45':
            exams[i] = exam_45
            updated = True
            print('Successfully updated exam-45 in exams.json')
            break

    if not updated:
        exams.append(exam_45)
        print('Appended exam-45 to exams.json')

    with open('data/exams.json', 'w', encoding='utf-8') as f:
        json.dump(exams, f, ensure_ascii=False, indent=2)

    with open('data/default_exams.json', 'w', encoding='utf-8') as f:
        json.dump(exams, f, ensure_ascii=False, indent=2)

    print('Both data/exams.json and data/default_exams.json updated successfully for exam-45!')

if __name__ == '__main__':
    update_exam45()
